constexpr Pricing kOpenRouter{"openrouter", 0.75e-6, 4.5e-6, 0.075e-6, 0.75e-6, 16000};
constexpr Pricing kAnthropic{"anthropic", 4e-6, 20e-6, 0.2e-6, 5e-6, 4000};
